"""D2 paper text/tables generated only from retained outputs and verified mathematics."""
import csv,json
from v3_revision import ROOT,RESULT,para,sub,eq,table

def augment_levy(c):
    out=RESULT/'round2/levy'
    if not (out/'paired-tests.csv').exists():return
    f=lambda x:'NA' if x in (None,'') else format(float(x),'.4g')
    rows=list(csv.DictReader((out/'summary.csv').open()));pairs=list(csv.DictReader((out/'paired-tests.csv').open()));sim=json.loads((out/'simulation.json').read_text())['results']
    c['sections'][3]['blocks'].extend([
      sub('Post-result / exploratory classical maximal-inequality benchmark'),
      para('Proposition 1 (classical Lévy bound, direct scalar application). Let the future real increments X<sub>1</sub>,…,X<sub>H</sub> be independent and individually symmetric about zero, with S<sub>0</sub>=0 and S<sub>h</sub>=∑<sub>j=1</sub><super>h</super>X<sub>j</sub>. They need not have the same distribution or finite moments. For a fixed starting position x, write B=|x| and q=inf{u:Pr(|S<sub>H</sub>|≤u)≥0.975}. Lévy’s maximal inequality implies the following strict-breach bound; Appendix J gives the proof. This is a classical result applied to this target, not a new theorem (Sussman, 2023, Proposition3.4).'),
      eq('Pr(max<sub>0≤h≤H</sub>|x+S<sub>h</sub>| &gt; B+q) ≤ Pr(max<sub>1≤h≤H</sub>|S<sub>h</sub>| &gt; q) ≤ 2Pr(|S<sub>H</sub>| &gt; q) ≤ 0.05.',r'\Pr\!\left(\max_{0\le h\le H}|x+S_h|>B+q\right)\le\Pr\!\left(\max_{1\le h\le H}|S_h|>q\right)\le 2\Pr(|S_H|>q)\le0.05.'),
      para('The operational report L uses the same frozen completed-origin pool and refit times as F. Its endpoint sample is |N<sub>i+H</sub>−N<sub>i</sub>| and its one-based order rank is ⌈39(W+1)/40⌉. Add the resulting estimate to B<sub>t</sub>. This empirical plug-in is distinct from the known population quantile in Proposition1. Overlapping endpoint samples and dependent, changing series do not inherit the proposition’s population coverage. Conditional coverage additionally requires the independence and symmetry premises and the correct endpoint quantile conditional on issue information. The bound supplies no pinball-loss ordering against F.')])
    table_rows=[]
    for r in rows:
        pp=[a for a in pairs if (a['source'],a['horizon'],a['window'])==(r['source'],r['horizon'],r['window'])];ff=next(a for a in pp if a['right_method']=='frozen_F');qq=next(a for a in pp if a['right_method']=='QR')
        table_rows.append(['FX' if r['source']=='fx_hourly' else 'Treasury',r['horizon'],r['window'],f(r['mean_pinball']),r['strict_breach_count']+'/'+r['origin_count'],f(ff['relative_loss_percent']),f(qq['relative_loss_percent']),f(ff['dm_p'])])
    c['sections'][7]['blocks'].extend([
      sub('Post-result / exploratory Lévy plug-in benchmark'),
      table('Table 9. All eight classical-bound plug-in L cells. Loss uses source-native units (FX USD; Treasury USD millions). Δ F/QR compares the same W and refit schedule; positive values are adverse for L. DM p is the unadjusted working-reference paired L–F test; Appendix J retains both comparators and a separate16-member Holm family. Original primaries are unchanged.', ['Source','H','W','Mean loss','Hits / n','Δ F %','Δ QR %','DM p vs F'],table_rows),
      para('The plug-in reduces FX breach counts relative to F in every cell while increasing pinball loss. In Treasury H24 it has both higher loss and more breach occasions than F; its Treasury H6/W260 loss is lower than F. Thus the empirical report does not have a uniform conservative or accuracy ordering. The oracle-quantile simulations in Appendix J remain below5% in all specified stationary Gaussian AR settings, including positive persistence. Those simulations furnish no counterexample for these settings and no general extension of the independence theorem.')])
    proof=[
      para('Proof of Proposition1. Let M=max<sub>1≤h≤H</sub>|S<sub>h</sub>| and let η be the first h with |S<sub>h</sub>|&gt;c. Split each event {η=k} by the sign of S<sub>k</sub>. The remaining sum R<sub>k</sub>=S<sub>H</sub>−S<sub>k</sub> is independent of information through k and symmetric. On a positive first crossing, R<sub>k</sub>≥0 ensures |S<sub>H</sub>|&gt;c; on a negative crossing, R<sub>k</sub>≤0 does so. Each half-axis has probability at least one half, including atoms at zero. Summing disjoint first-crossing events yields Pr(M&gt;c)≤2Pr(|S<sub>H</sub>|&gt;c). This includes c=0 directly. The triangle inequality gives max<sub>0≤h≤H</sub>|x+S<sub>h</sub>|≤|x|+M, while right continuity of the endpoint distribution gives Pr(|S<sub>H</sub>|&gt;q)≤0.025. These facts prove the stated corollary with strict breaches even for distributions with atoms.'),
      para('The claim can fail without independence: take X<sub>1</sub>=Z and X<sub>2</sub>=−Z, where Z takes −1 and1 equally. Both marginals are symmetric, but S<sub>2</sub>=0 and M=1. At x=q=0 the peak exceeds the threshold with probability one. This exact counterexample is separate from the positive-AR simulation. A conditional use of the proof must establish the corresponding premises under the conditional law.'),
      para('The simulation uses independently initialized stationary Gaussian increment paths with unit marginal variance and innovations of variance1−φ². The known endpoint variance is H+2∑<sub>j=1</sub><super>H−1</super>(H−j)φ<super>j</super>, so the absolute-endpoint0.975quantile uses the normal probability0.9875. Starting x=0 makes this an unconditional population-threshold experiment. It isolates serial dependence from empirical-quantile estimation error. Each cell has100000 paths and a fixed recorded seed; Monte Carlo standard errors accompany observed rates. Positive φ violates independence but does not logically require violation of the numerical bound.'),
      table('Table J1. Oracle-quantile simulation. Rates/SE are percentages; Δ5 is percentage points from5%. Endpoint tails are evaluated at the same threshold. Every specified cell is retained.', ['H','φ','Oracle q','Max rate %','Endpoint %','Δ5 pp','MC SE %'],[[str(r['horizon']),f(r['phi']),f(r['oracle_abs_endpoint_quantile']),f(100*r['max_exceedance_rate']),f(100*r['endpoint_exceedance_rate']),f(100*r['rate_minus_point05']),f(100*r['monte_carlo_standard_error'])] for r in sim]),
      table('Table J2. Every post-result / exploratory L comparison. Negative t/Δloss favors L. Holm uses only this new16-comparison family; the original72-member family is unchanged. Component p values are approximate working references with shared-training and post-inspection limitations.', ['Source','H','W','Ref','Δloss %','DM t','DM p','HLN p','Holm p'],[['FX' if r['source']=='fx_hourly' else 'Treasury',r['horizon'],r['window'],r['right_method'].removeprefix('frozen_'),f(r['relative_loss_percent']),f(r['dm_t']),f(r['dm_p']),f(r['hln_p']),f(r['holm_p'])] for r in pairs])]
    c['sections'].append(dict(title='Appendix J. Classical bound proof and exploratory L outputs',blocks=proof))
    c['references'].append(dict(id='sussman2023',html="Sussman, E. (2023). A strengthened Orlicz–Pettis theorem via Itô–Nisio. <i>Annals of Functional Analysis</i> 14, article22, Proposition3.4. <a href='https://doi.org/10.1007/s43034-022-00225-1'>DOI:10.1007/s43034-022-00225-1</a>."))
    from round2_levy_ar_manuscript import augment_ar_correction
    augment_ar_correction(c)
